const ignorePatterns = ["node_modules/", ".env"];
function shouldIgnore(file) {
  return ignorePatterns.some((p) => file.startsWith(p));
}
console.log(shouldIgnore("node_modules/lodash/index.js"));
console.log(shouldIgnore("src/app.js"));

