exercises.solution:
function checkEnv(env, required) {
  const missing = required.filter((k) => !env[k]);
  if (missing.length === 0) {
    console.log("all good");
  } else {
    missing.forEach((k) => console.log("missing: " + k));
  }
}
checkEnv({ PORT: "3000" }, ["PORT", "DATABASE_URL"]);

