exercises.solution:
const env = { PORT: "5000" };
function buildConfig(env) {
  return {
    port: env.PORT || 3000,
    nodeEnv: env.NODE_ENV || "development"
  };
}
console.log(JSON.stringify(buildConfig(env)));

